(() => {
  const panel = document.querySelector('[role="tabpanel"]');
  if (!panel) return 'no tabpanel';
  const labels = [...panel.querySelectorAll('label, .form-label, [class*="label"]')].map(el => el.textContent.trim()).filter(Boolean);
  const inputs = [...panel.querySelectorAll('input, select, textarea')].map(el => ({
    tag: el.tagName,
    type: el.type,
    name: el.name,
    id: el.id,
    placeholder: el.placeholder,
    ariaLabel: el.getAttribute('aria-label'),
    value: el.value,
    required: el.required
  }));
  return JSON.stringify({labels, inputs}, null, 2);
})()

(() => {
  const panel = document.querySelector('#data-tab-panel-bszml17zpd');
  // Check for required attribute or CSS classes indicating required
  const fields = [...panel.querySelectorAll('input, select, textarea')];
  const req = fields.filter(f => f.required || f.hasAttribute('required'));
  // Also check labels with asterisk in text
  const labels = [...panel.querySelectorAll('label, span, div')].filter(el => {
    const t = el.textContent;
    return t.includes('*') && t.length < 60;
  });
  return JSON.stringify({
    requiredFields: req.map(f => f.name || 'unnamed'),
    asteriskLabels: labels.map(l => l.textContent.trim())
  });
})()

