(() => {
  const listbox = document.querySelector('[aria-label="Items"], [role="listbox"]');
  const options = [...listbox.querySelectorAll('[role="option"]')];
  const target = options.find(o => o.textContent.includes('fwat2-n1 MTP Item B'));
  if (!target) return 'not found';
  // Get the status marker - look for the span with "P" or check aria-label
  const firstCell = target.firstElementChild;
  const statusEl = firstCell?.querySelector('span, [aria-label]');
  return JSON.stringify({
    firstCellHTML: firstCell?.outerHTML?.slice(0, 500),
    statusAriaLabel: statusEl?.getAttribute('aria-label'),
    statusText: statusEl?.textContent?.trim()
  });
})()

(() => {
